1	import * as THREE from "three";
2	import { BlockId, voxelRaycast } from "@/lib/world";
3	import {
4	  BREED_FED_WINDOW_SECONDS,
5	  CHEST_SLOTS,
6	  EYE_HEIGHT,
7	  MINE_REACH,
8	  SLEEP_ALLOWED_BELOW_DAYLIGHT,
9	  SLEEP_FADE_SECONDS,
10	  SLEEP_HOSTILE_RADIUS
11	} from "@/lib/game/config";
12	import { adjustSlotCount, consumeToolDurability } from "@/lib/game/inventory";
13	import { createEmptySlot } from "@/lib/game/items";
14	import type { MobKind } from "@/lib/game/types";
15	import type { EmitGameEvent, GameState } from "../state";
16	import { findAimedMobIndex } from "./combat";
17	import { fillDungeonChestIfUnlooted } from "./dungeon";
18	import { lookDirection } from "./playerMotion";
19	
20	const scratchEye = new THREE.Vector3();
21	const scratchDir = new THREE.Vector3();
22	
23	/** Blocks whose right-click runs a handler instead of placing the held block. */
24	export type InteractiveKind = "bed" | "furnace" | "chest";
25	
26	export const INTERACTIVE_BLOCKS: Partial<Record<BlockId, InteractiveKind>> = {
27	  [BlockId.Bed]: "bed",
28	  [BlockId.Furnace]: "furnace",
29	  [BlockId.Chest]: "chest"
30	};
31	
32	/**
33	 * Right-click "use" on the aimed block. Returns true when the click was an
34	 * interaction (consumed — the caller must NOT then place a block), false when
35	 * the aimed block has no behavior and placement should proceed.
36	 *
37	 * This is the shared hook future interactive blocks (furnace, …) plug into:
38	 * add a `BlockId → kind` entry and a branch below.
39	 */
40	export function tryInteractBlock(state: GameState, emit: EmitGameEvent): boolean {
41	  const { world, player } = state;
42	  scratchEye.set(player.position.x, player.position.y + EYE_HEIGHT, player.position.z);
43	  lookDirection(player.yaw, player.pitch, scratchDir);
44	  const result = voxelRaycast(world, scratchEye, scratchDir, MINE_REACH);
45	  if (!result) return false;
46	
47	  const block = world.get(result.hit.x, result.hit.y, result.hit.z) as BlockId;
48	  const kind = INTERACTIVE_BLOCKS[block];
49	  if (!kind) return false;
50	
51	  if (kind === "bed") return interactBed(state, emit, result.hit.x, result.hit.y, result.hit.z);
52	  if (kind === "furnace") return interactFurnace(state, emit);
53	  if (kind === "chest") return interactChest(state, emit, result.hit.x, result.hit.y, result.hit.z);
54	  return false;
55	}
56	
57	/** Opens the chest at (x,y,z) in the inventory panel, creating its (lazy) empty store. */
58	function interactChest(state: GameState, emit: EmitGameEvent, x: number, y: number, z: number): boolean {
59	  const idx = state.world.index(x, y, z);
60	  if (!state.containers.has(idx)) {
61	    state.containers.set(
62	      idx,
63	      Array.from({ length: CHEST_SLOTS }, () => createEmptySlot())
64	    );
65	  }
66	  // A worldgen dungeon chest rolls its loot here, on first open (then never again).
67	  fillDungeonChestIfUnlooted(state, idx);
68	  state.openContainerIndex = idx;
69	  state.inventoryOpen = true;
70	  emit({ type: "openedContainer" });
71	  return true;
72	}
73	
74	/** What each breedable animal is fed to enter "in love" mode. */
75	const FEED_ITEMS: Partial<Record<MobKind, string>> = {
76	  sheep: "wheat",
77	  horse: "wheat",
78	  chicken: "seeds"
79	};
80	
81	/**
82	 * Right-click an adult animal with its feed item to put it "in love" (toward
83	 * breeding). First in the right-click precedence so feeding wins over placing or
84	 * tilling when an animal is in the crosshair. Returns true when an animal was fed.
85	 */
86	export function tryFeedAimedMob(state: GameState, emit: EmitGameEvent): boolean {
87	  const slot = state.inventory[state.selectedSlot];
88	  if (!slot?.id || slot.count <= 0) return false;
89	  const index = findAimedMobIndex(state);
90	  if (index < 0) return false;
91	  const mob = state.mobs[index];
92	  if (mob.hostile || FEED_ITEMS[mob.kind] !== slot.id) return false;
93	  if (mob.ageTimer > 0 || mob.fedTimer > 0) return false; // babies and already-in-love animals decline
94	
95	  state.inventory = adjustSlotCount(state.inventory, slot.id, -1, state.selectedSlot) ?? state.inventory;
96	  mob.fedTimer = BREED_FED_WINDOW_SECONDS;
97	  emit({ type: "mobFed", kind: mob.kind });
98	  return true;
99	}
100	
101	/** Opens the inventory in furnace mode so its smelting recipes unlock. */
102	function interactFurnace(state: GameState, emit: EmitGameEvent): boolean {
103	  state.inventoryOpen = true;
104	  state.craftingStation = "furnace";
105	  emit({ type: "openedStation", station: "furnace" });
106	  return true;
107	}
108	
109	/** Sleep in a bed: only at night, only when no hostile is near. Sets the respawn point. */
110	function interactBed(state: GameState, emit: EmitGameEvent, x: number, y: number, z: number): boolean {
111	  if (state.daylight >= SLEEP_ALLOWED_BELOW_DAYLIGHT) {
112	    emit({ type: "sleepDenied", reason: "daylight" });
113	    return true;
114	  }
115	  for (const mob of state.mobs) {
116	    if (mob.hostile && mob.position.distanceTo(state.player.position) <= SLEEP_HOSTILE_RADIUS) {
117	      emit({ type: "sleepDenied", reason: "hostiles" });
118	      return true;
119	    }
120	  }
121	
122	  state.spawnPoint = { x, y, z };
123	  state.sleepTimer = SLEEP_FADE_SECONDS;
124	  emit({ type: "sleepStarted" });
125	  return true;
126	}
127	
128	/**
129	 * Right-click "use" of the held item on the aimed block: a hoe tills grass/dirt
130	 * into farmland, seeds plant wheat on farmland. Returns true when an action
131	 * happened (consumes the click), false to fall through to block placement.
132	 */
133	export function tryUseHeldItem(state: GameState, emit: EmitGameEvent, rng: () => number): boolean {
134	  void rng; // reserved for future randomized uses (bone meal, …)
135	  const slot = state.inventory[state.selectedSlot];
136	  if (!slot?.id || slot.count <= 0) return false;
137	  const isHoe = slot.id.endsWith("_hoe");
138	  const isSeeds = slot.id === "seeds";
139	  if (!isHoe && !isSeeds) return false;
140	
141	  const { world, player } = state;
142	  scratchEye.set(player.position.x, player.position.y + EYE_HEIGHT, player.position.z);
143	  lookDirection(player.yaw, player.pitch, scratchDir);
144	  const result = voxelRaycast(world, scratchEye, scratchDir, MINE_REACH);
145	  if (!result) return false;
146	  const { x, y, z } = result.hit;
147	  const block = world.get(x, y, z) as BlockId;
148	
149	  if (isHoe) {
150	    if (block !== BlockId.Grass && block !== BlockId.Dirt) return false;
151	    state.blockChanges.set(x, y, z, BlockId.Farmland);
152	    state.inventory = consumeToolDurability(state.inventory, state.selectedSlot, 1) ?? state.inventory;
153	    state.worldMeshDirty = true;
154	    emit({ type: "tilledSoil" });
155	    return true;
156	  }
157	
158	  // Seeds: plant on farmland when the cell above is clear.
159	  if (block !== BlockId.Farmland || world.get(x, y + 1, z) !== BlockId.Air) return false;
160	  state.blockChanges.set(x, y + 1, z, BlockId.WheatStage0);
161	  state.inventory = adjustSlotCount(state.inventory, slot.id, -1, state.selectedSlot) ?? state.inventory;
162	  state.worldMeshDirty = true;
163	  emit({ type: "plantedSeed" });
164	  return true;
165	}
166

