42	  paused: false,
43	  debugOpen: false,
44	  debug: null,
45	  cameraMode: "first",
46	  armorPoints: 0,
47	  capsActive: false,
48	  sleeping: false,
49	  craftingStation: null,
50	  container: null
51	};
