53	const noopSubscribe = () => () => {};
54	
55	type GameContext = { engine: GameEngine; node: HTMLDivElement };
56	
57	// Debug/test handle: lets the browser console and the Playwright E2E suite
58	// inspect the live simulation (single-player client game — nothing to protect).
59	declare global {
60	  interface Window {
61	    __monecraft?: { engine: GameEngine; renderer: GameRenderer; input: InputController; audio: AudioDirector };
62	  }
63	}
