74	export function useMinecraftGame() {
75	  const [ctx, setCtx] = useState<GameContext | null>(null);
76	  const [locked, setLocked] = useState(false);
77	  const [saveMessage, setSaveMessage] = useState("");
78	  const [rendererError, setRendererError] = useState<string | null>(null);
79	  const [audioSettings, setAudioSettings] = useState<AudioSettings>(DEFAULT_AUDIO_SETTINGS);
80	  const canvasRef = useRef<HTMLCanvasElement | null>(null);
81	  const minimapNodeRef = useRef<HTMLDivElement | null>(null);
82	  const audioRef = useRef<AudioDirector | null>(null);
83	  // The rAF effect must not re-run on volume tweaks — it reads through a ref.
84	  const audioSettingsRef = useRef(audioSettings);
85	  const [skinId, setSkinId] = useState<SkinId>(DEFAULT_SKIN_ID);
86	  const skinIdRef = useRef(skinId);
87	  const rendererRef = useRef<GameRenderer | null>(null);
88	
89	  // Persisted preferences load after mount: render never touches localStorage
90	  // (SSR), and the setState hops a microtask like the renderer-error report.
91	  // This effect runs before the renderer effect (ctx is set by a callback ref
92	  // in a later commit), so the refs are populated by the time either exists.
93	  useEffect(() => {
94	    const stored = readAudioSettings();
95	    audioSettingsRef.current = stored;
96	    audioRef.current?.setSettings(stored);
97	    const { skinId: storedSkin } = readSkinSettings();
98	    skinIdRef.current = storedSkin;
99	    queueMicrotask(() => {
100	      setAudioSettings(stored);
101	      setSkinId(storedSkin);
102	    });
103	  }, []);
104	
105	  const updateAudioSettings = useCallback((partial: Partial<AudioSettings>) => {
106	    const next = { ...audioSettingsRef.current, ...partial };
107	    audioSettingsRef.current = next;
108	    setAudioSettings(next);
109	    writeAudioSettings(next);
110	    audioRef.current?.setSettings(next);
111	  }, []);
112	
113	  const updateSkin = useCallback((id: SkinId) => {
114	    skinIdRef.current = id;
115	    setSkinId(id);
116	    writeSkinSettings({ skinId: id });
117	    rendererRef.current?.setPlayerSkin(getSkinPreset(id).palette);
118	  }, []);
119	
120	  // Callback ref: the engine boots as soon as the canvas mount exists. A ref
121	  // callback runs during commit, where side effects and setState are legal.
122	  const attachMount = useCallback((node: HTMLDivElement | null) => {
123	    if (!node) {
124	      setCtx(null);
125	      return;
126	    }
127	    setCtx({ engine: new GameEngine({ save: readSave(SAVE_KEY) }), node });
128	  }, []);
